-- The Chennai Residency — MySQL / MariaDB schema (InnoDB, utf8mb4)
-- Works on MySQL 5.7+, MySQL 8, MariaDB 10.3+. Safe to run repeatedly.
-- All timestamps are stored in UTC. IDs are UUID strings generated by the app.
-- JSON data is stored as LONGTEXT (works on every MySQL/MariaDB version).

CREATE TABLE IF NOT EXISTS staff_users (
 id CHAR(36) NOT NULL,
 email VARCHAR(190) NOT NULL,
 display_name VARCHAR(255) NOT NULL,
 password_hash VARCHAR(255) NOT NULL,
 role ENUM('admin','manager','reception','housekeeping','accounts','auditor') NOT NULL,
 active TINYINT(1) NOT NULL DEFAULT 1,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 PRIMARY KEY (id),
 UNIQUE KEY staff_users_email_uq (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS devices (
 id CHAR(36) NOT NULL,
 device_code VARCHAR(100) NOT NULL,
 device_name VARCHAR(100) NOT NULL,
 platform VARCHAR(20) NOT NULL DEFAULT 'web',
 status ENUM('pending','approved','blocked') NOT NULL DEFAULT 'pending',
 approved_by CHAR(36) NULL,
 approved_at DATETIME(3) NULL,
 last_seen_at DATETIME(3) NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY (id),
 UNIQUE KEY devices_code_uq (device_code),
 CONSTRAINT devices_approved_by_fk FOREIGN KEY (approved_by) REFERENCES staff_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS hotel_state (
 id TINYINT NOT NULL DEFAULT 1,
 revision BIGINT UNSIGNED NOT NULL DEFAULT 0,
 payload LONGTEXT NOT NULL,
 updated_by CHAR(36) NULL,
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY (id),
 CONSTRAINT hotel_state_user_fk FOREIGN KEY (updated_by) REFERENCES staff_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO hotel_state (id, revision, payload) VALUES (1, 0, '{}');

CREATE TABLE IF NOT EXISTS state_revisions (
 revision BIGINT UNSIGNED NOT NULL,
 user_id CHAR(36) NULL,
 device_id CHAR(36) NULL,
 changed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 summary TEXT NOT NULL,
 PRIMARY KEY (revision),
 CONSTRAINT state_rev_user_fk FOREIGN KEY (user_id) REFERENCES staff_users(id),
 CONSTRAINT state_rev_device_fk FOREIGN KEY (device_id) REFERENCES devices(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_events (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 user_id CHAR(36) NULL,
 device_id CHAR(36) NULL,
 action VARCHAR(100) NOT NULL,
 entity_type VARCHAR(100) NULL,
 entity_id VARCHAR(100) NULL,
 details TEXT NULL,
 ip VARCHAR(45) NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY (id),
 KEY audit_events_created_idx (created_at),
 CONSTRAINT audit_user_fk FOREIGN KEY (user_id) REFERENCES staff_users(id),
 CONSTRAINT audit_device_fk FOREIGN KEY (device_id) REFERENCES devices(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS property_issues (
 id CHAR(36) NOT NULL,
 issue_key VARCHAR(190) NOT NULL,
 room_number VARCHAR(50) NULL,
 title VARCHAR(255) NOT NULL,
 description TEXT NULL,
 severity VARCHAR(20) NOT NULL DEFAULT 'warning',
 status ENUM('open','in_progress','resolved') NOT NULL DEFAULT 'open',
 evidence LONGTEXT NOT NULL,
 reported_by CHAR(36) NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 resolved_at DATETIME(3) NULL,
 PRIMARY KEY (id),
 UNIQUE KEY property_issues_key_uq (issue_key),
 CONSTRAINT issues_reporter_fk FOREIGN KEY (reported_by) REFERENCES staff_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS push_subscriptions (
 id CHAR(36) NOT NULL,
 user_id CHAR(36) NOT NULL,
 device_id CHAR(36) NULL,
 subscription TEXT NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY (id),
 UNIQUE KEY push_user_device_uq (user_id, device_id),
 CONSTRAINT push_user_fk FOREIGN KEY (user_id) REFERENCES staff_users(id) ON DELETE CASCADE,
 CONSTRAINT push_device_fk FOREIGN KEY (device_id) REFERENCES devices(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
